const src = $('Vapi Tools').first().json;
const root = src.body ?? src;
const m = root.message ?? root;
let calls = [];
if (Array.isArray(m.toolCallList)) calls = m.toolCallList;
else if (Array.isArray(m.toolCalls)) calls = m.toolCalls.map(t => ({ toolCallId: t.id, function: t.function }));
else if (m.functionCall) calls = [{ toolCallId: m.toolCallId ?? m.call?.id, function: m.functionCall }];

const lead_id = String(m.call?.metadata?.lead_id ?? m.metadata?.lead_id ?? '');
const call_id = String(m.call?.id ?? m.callId ?? '');
const telefono = String(m.call?.customer?.number ?? m.customer?.number ?? m.call?.metadata?.telefono ?? '');
const estado_actual = String(m.call?.metadata?.estado ?? m.metadata?.estado ?? '');

function normalizarInicio(value) {
  const texto = String(value || '').trim();
  if (!texto) return '';
  const conOffset = /(?:Z|[+-]\d{2}:?\d{2})$/.test(texto);
  const dt = conOffset
    ? DateTime.fromISO(texto, { setZone: true })
    : DateTime.fromISO(texto, { zone: 'Europe/Madrid' });
  if (!dt.isValid) return texto;
  return dt.setZone('Europe/Madrid').toISO();
}

return calls.map(c => {
  let args = c.function?.arguments ?? {};
  if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
  if (args && typeof args === 'object' && args.inicio) args.inicio = normalizarInicio(args.inicio);
  return { json: { toolCallId: c.toolCallId ?? c.id, name: c.function?.name, args, lead_id, call_id, telefono, estado_actual } };
});

const cfg = $('Config').first().json;
const tool = $('Normalizar tool calls').item.json;
const args = tool.args || {};
const busyRaw = $json.data || [];
const busy = busyRaw.map(b => [new Date(b.start).getTime(), new Date(b.end).getTime()]);

const tz = cfg.timezone || 'Europe/Madrid';
const dur = Number(cfg.duracion_cita || 30);
const buffer = Number(cfg.buffer_min || 15);
const now = DateTime.now().setZone(tz);
const minStart = now.plus({ hours: 3 });

// Rango pedido por la herramienta (si no llega, proximos 7 dias)
let desde = args.desde ? DateTime.fromISO(String(args.desde), { setZone: true }).setZone(tz) : now;
let hasta = args.hasta ? DateTime.fromISO(String(args.hasta), { setZone: true }).setZone(tz) : now.plus({ days: 7 });
if (!desde.isValid) desde = now;
if (!hasta.isValid) hasta = now.plus({ days: 7 });
if (hasta < desde) hasta = desde;

const iniDia = desde.startOf('day');
const finDia = hasta.startOf('day');

// Horario del especialista (hora de Madrid). La reunion de 30 min cabe en la franja.
const MANANA = [9, 9.5, 10, 10.5];              // 09:00 - 11:00
const TARDE  = [14, 14.5, 15, 15.5, 16, 16.5];  // 14:00 - 17:00
const HORAS = MANANA.concat(TARDE);
const MAX_DIAS = 3; // tope para no devolver una lista gigante

const out = [];
let dias = 0;

for (let d = 0; d <= 30 && dias < MAX_DIAS; d++) {
  const day = iniDia.plus({ days: d });
  if (day > finDia) break;
  if (day.weekday > 6) continue; // lunes a sabado (7 = domingo)

  let delDia = 0;
  for (const h of HORAS) {
    const s = day.plus({ minutes: Math.round(h * 60) });
    const e = s.plus({ minutes: dur });
    if (s < minStart || s < desde) continue;
    const sMs = s.toMillis(), eMs = e.toMillis();
    const clash = busy.some(([bs, be]) => sMs < be + buffer * 60000 && eMs > bs - buffer * 60000);
    if (clash) continue;
    out.push(s);
    delDia++;
  }
  if (delDia > 0) dias++;
}

const label = dt => dt.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' HH:mm") + ' [' + dt.toISO() + ']';
const result = out.length
  ? 'Huecos libres (hora de Madrid): ' + out.map(label).join('; ') + '. Al crear la cita copia el valor entre corchetes tal cual, sin recalcular la hora.'
  : 'No hay huecos libres en ese rango de fechas. Ofrece otro dia y vuelve a consultar.';

return [{ json: { results: [{ toolCallId: tool.toolCallId, result }], slots: out.map(d => d.toISO()) } }];

const tool = $('Normalizar tool calls').item.json;
const res = $json || {};
const ev = res.data || {};
const args = tool.args || {};
const cfg = $('Config').first().json;
const dur = Number(cfg.duracion_cita || 30);

const inicioDt = DateTime.fromISO(String(args.inicio || ''), { setZone: true }).setZone('Europe/Madrid');
const fechaTxt = inicioDt.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' HH:mm");
const diaTxt = inicioDt.toFormat('dd/MM/yyyy');
const horaTxt = inicioDt.toFormat('HH:mm');

const meet = ev.hangoutLink || cfg.meet_link_fijo || '';
const nombre = args.nombre || tool.nombre || '';

const resp = 'Cita confirmada: ' + fechaTxt + '. Te acabo de enviar el enlace de la videollamada por WhatsApp.';

const texto = 'Hola' + (nombre ? ' ' + nombre : '') + ', soy Julian, de Rose Holding IA.'
  + '\n\nTu reunion de diagnostico queda confirmada:'
  + '\n- ' + fechaTxt + ' (hora de Madrid)'
  + '\n- Duracion: ' + dur + ' minutos'
  + (meet ? '\n- Videollamada: ' + meet : '')
  + '\n\nSi necesitas cambiarla, responde a este mensaje.';

return [{ json: {
  cita_id: 'CIT-' + (tool.call_id || Date.now()),
  lead_id: tool.lead_id,
  fecha: diaTxt,
  hora: horaTxt,
  inicio: inicioDt.toISO(),
  fin: inicioDt.plus({ minutes: dur }).toISO(),
  estado: 'confirmada',
  event_id: ev.id || '',
  meet_link: meet,
  creada_por: 'agente_voz',
  calendar_used: ev.calendarUsed || '',
  _respuesta: resp,
  _whatsapp_texto: texto,
  _toolCallId: tool.toolCallId
} }];

const tool = $('Normalizar tool calls').item.json;
const a = tool.args || {};
const TERMINALES = ['cita_agendada', 'no_interesado', 'humano'];
const row = { id: tool.lead_id };
if (!TERMINALES.includes(String(tool.estado_actual || '').toLowerCase())) row.estado = 'contactado';
for (const k of ['nombre', 'empresa', 'sector', 'tamano', 'problema', 'procesos_manuales', 'quiere_automatizar', 'urgencia', 'email']) {
  if (a[k] !== undefined && a[k] !== null && a[k] !== '') row[k] = a[k];
}
if (a.decisor !== undefined) row.decisor = a.decisor ? 'si' : 'no';
row._respuesta = 'Datos guardados.';
row._toolCallId = tool.toolCallId;
return [{ json: row }];
